-- supabase/seed.sql
-- Generated by scripts/generate-seed-sql.ts from the app's own Phase 1-9 mock data
-- (lib/mock/*.ts, lib/constants/documentation-templates.ts) — regenerate this file
-- any time that mock data changes rather than hand-editing it.
--
-- Run against a fresh project (after the migrations in supabase/migrations/ have
-- applied) with the Supabase CLI: `supabase db execute -f supabase/seed.sql`, or
-- paste it into the SQL Editor. It assumes exactly one signed-up user — the HVA —
-- and looks up that user's id (the earliest-created row in auth.users) so every
-- row's `user_id` can be set explicitly, since there is no authenticated request
-- context (and so no auth.uid()) when running a seed script from the SQL Editor
-- or CLI.
--
-- NOTE: Open Loops, Activities, Documentation History, Workflow Runs, and
-- Communication Logs are NOT seeded here. Phase 1-9's mock data for those was
-- written to make the mock in-memory services demonstrate cross-module features
-- (matching patient names across modules, etc.) and is intentionally NOT carried
-- into the real database — a production HVA account should start with a clean
-- slate for its own day-to-day activity. Only genuinely reusable reference/setup
-- data — Patients, Providers, Documentation Templates, and Clinic Contacts (with
-- their Communication Logs) — is seeded.

do $$
declare
  v_user_id uuid;
begin
  select id into v_user_id from auth.users order by created_at asc limit 1;
  if v_user_id is null then
    raise exception 'No user found in auth.users — sign up the HVA account first, then re-run this seed.';
  end if;

  -- documentation_templates: shared reference data, no user_id

  -- providers

  -- patients

  -- clinic_contacts, each followed by its own communication_logs rows
  declare v_contact_id uuid; begin
  end;
  declare v_contact_id uuid; begin
  end;
  declare v_contact_id uuid; begin
  end;
  declare v_contact_id uuid; begin
  end;
  declare v_contact_id uuid; begin
  end;
  declare v_contact_id uuid; begin
  end;
  declare v_contact_id uuid; begin
  end;
  declare v_contact_id uuid; begin
  end;
  declare v_contact_id uuid; begin
  end;

end $$;

